@Composable
fun MusicianScreen(
    navController: NavController,
    viewModel: AudioEngineViewModel = viewModel()
) {
    val state by viewModel.uiState.collectAsState()
    val musician = state.musicianState
    val spl = state.currentSpl
    val geo = state.geoInfo

    val infiniteTransition = rememberInfiniteTransition(label = "pulse")
    val pulseAlpha by infiniteTransition.animateFloat(
        initialValue = 0.15f,
        targetValue = 0.4f,
        animationSpec = infiniteRepeatable(tween(1000), RepeatMode.Reverse),
        label = "pulseAlpha"
    )

    Box(
        modifier = Modifier
            .fillMaxSize()
            .background(
                Brush.verticalGradient(
                    colors = listOf(AbyssBlack, SurfaceTeal.copy(alpha = 0.5f))
                )
            )
    ) {
        Column(
            modifier = Modifier
                .fillMaxSize()
                .verticalScroll(rememberScrollState())
                .padding(horizontal = 16.dp)
        ) {
            Spacer(modifier = Modifier.height(12.dp))

            // Header
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.SpaceBetween,
                verticalAlignment = Alignment.CenterVertically
            ) {
                Text(
                    "Modo Musico",
                    style = MaterialTheme.typography.headlineSmall,
                    color = TextPrimary,
                    fontWeight = FontWeight.Bold
                )
                Switch(
                    checked = musician.isActive,
                    onCheckedChange = { viewModel.setMusicianMode(it) }
                )
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Stage visualization
            StageCanvas(
                spl = spl,
                isOverLimit = musician.isOverLimit,
                hasGpsFix = musician.hasGpsFix,
                pulseAlpha = pulseAlpha,
                modifier = Modifier
                    .fillMaxWidth()
                    .height(280.dp)
                    .clip(RoundedCornerShape(16.dp))
                    .background(SurfaceTeal)
            )

            Spacer(modifier = Modifier.height(12.dp))

            // GPS info
            GlassCard(modifier = Modifier.fillMaxWidth()) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    verticalAlignment = Alignment.CenterVertically,
                    horizontalArrangement = Arrangement.spacedBy(10.dp)
                ) {
                    Icon(
                        Icons.Filled.LocationOn,
                        contentDescription = null,
                        tint = if (musician.hasGpsFix) CyanGlow else MaterialTheme.colorScheme.outline,
                        modifier = Modifier.size(20.dp)
                    )
                    Column(modifier = Modifier.weight(1f)) {
                        Text(
                            text = if (musician.hasGpsFix) geo.label else "Sin GPS",
                            style = MaterialTheme.typography.bodyMedium,
                            color = TextPrimary,
                            fontWeight = FontWeight.Medium
                        )
                        Text(
                            text = if (musician.hasGpsFix) {
                                "%.4f, %.4f · %.0fm".format(musician.latitude, musician.longitude, musician.altitude)
                            } else "Activa GPS para seguimiento",
                            style = MaterialTheme.typography.labelSmall,
                            color = MaterialTheme.colorScheme.onSurfaceVariant
                        )
                    }
                    if (musician.hasGpsFix) {
                        StatusPill(text = "%.0fm PA".format(musician.distanceToPaM), color = CyanPrimary)
                    }
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // SPL reading - large
            GlassCard(modifier = Modifier.fillMaxWidth()) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column {
                        Text("SPL en tu posicion", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                        val splColor = when {
                            spl >= musician.safeSplLimit -> CoralAlert
                            spl >= musician.safeSplLimit - 15f -> AmberAccent
                            spl > 0f -> LimeActive
                            else -> MaterialTheme.colorScheme.outline
                        }
                        Text(
                            text = if (spl > 0f) "%.0f dB".format(spl) else "-- dB",
                            style = MaterialTheme.typography.displaySmall,
                            color = splColor,
                            fontWeight = FontWeight.Bold
                        )
                    }
                    if (spl >= musician.safeSplLimit) {
                        StatusPill(text = "Sobre limite", color = CoralAlert)
                    } else if (spl > 0f) {
                        StatusPill(text = "Seguro", color = LimeActive)
                    }
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // More me / Less me buttons
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(12.dp)
            ) {
                Button(
                    onClick = { viewModel.lessMe() },
                    modifier = Modifier
                        .weight(1f)
                        .height(56.dp),
                    shape = RoundedCornerShape(14.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = SurfaceElevated,
                        contentColor = AmberAccent
                    )
                ) {
                    Icon(Icons.Filled.VolumeDown, contentDescription = null)
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Menos yo", fontWeight = FontWeight.SemiBold)
                }
                Button(
                    onClick = { viewModel.moreMe() },
                    modifier = Modifier
                        .weight(1f)
                        .height(56.dp),
                    shape = RoundedCornerShape(14.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = CyanPrimary.copy(alpha = 0.2f),
                        contentColor = CyanGlow
                    )
                ) {
                    Icon(Icons.Filled.VolumeUp, contentDescription = null)
                    Spacer(modifier = Modifier.width(6.dp))
                    Text("Mas yo", fontWeight = FontWeight.SemiBold)
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // Personal volume
            GlassCard(modifier = Modifier.fillMaxWidth()) {
                Column(modifier = Modifier.fillMaxWidth()) {
                    Row(
                        modifier = Modifier.fillMaxWidth(),
                        horizontalArrangement = Arrangement.SpaceBetween
                    ) {
                        Text("Volumen personal", style = MaterialTheme.typography.labelMedium, color = MaterialTheme.colorScheme.onSurfaceVariant)
                        Text(
                            "%d%% · %+.1f dB".format(musician.volumePercent, musician.personalGainDb),
                            style = MaterialTheme.typography.labelMedium,
                            color = CyanGlow,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                    Spacer(modifier = Modifier.height(8.dp))
                    Slider(
                        value = musician.personalVolume,
                        onValueChange = { viewModel.setPersonalVolume(it) },
                        colors = SliderDefaults.colors(
                            thumbColor = CyanGlow,
                            activeTrackColor = CyanPrimary,
                            inactiveTrackColor = SurfaceElevated
                        )
                    )
                }
            }

            Spacer(modifier = Modifier.height(12.dp))

            // Delay compensation
            GlassCard(modifier = Modifier.fillMaxWidth()) {
                Row(
                    modifier = Modifier.fillMaxWidth(),
                    horizontalArrangement = Arrangement.SpaceBetween,
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Column {
                        Text("Delay compensado", style = MaterialTheme.typography.labelSmall, color = MaterialTheme.colorScheme.onSurfaceVariant)
                        Text(
                            "%.1f ms".format(musician.recommendedDelayMs),
                            style = MaterialTheme.typography.titleMedium,
                            color = AmberAccent,
                            fontWeight = FontWeight.SemiBold
                        )
                    }
                    Text(
                        "Vel. sonido: %.0f m/s".format(geo.speedOfSound),
                        style = MaterialTheme.typography.labelSmall,
                        color = MaterialTheme.colorScheme.onSurfaceVariant
                    )
                }
            }

            Spacer(modifier = Modifier.height(16.dp))

            // GPS tracking button
            if (!musician.hasGpsFix && musician.isActive) {
                Button(
                    onClick = { viewModel.startMusicianTracking() },
                    modifier = Modifier
                        .fillMaxWidth()
                        .height(48.dp),
                    shape = RoundedCornerShape(12.dp),
                    colors = ButtonDefaults.buttonColors(
                        containerColor = CyanPrimary,
                        contentColor = Color.Black
                    )
                ) {
                    Icon(Icons.Filled.MyLocation, contentDescription = null)
                    Spacer(modifier = Modifier.width(8.dp))
                    Text("Iniciar seguimiento GPS", fontWeight = FontWeight.SemiBold)
                }
            }

            Spacer(modifier = Modifier.height(24.dp))
        }
    }
}

@Composable
private fun StageCanvas(
    spl: Float,
    isOverLimit: Boolean,
    hasGpsFix: Boolean,
    pulseAlpha: Float,
    modifier: Modifier = Modifier
) {
    Canvas(modifier = modifier) {
        val w = size.width
        val h = size.height

        // Background gradient
        drawRect(
            brush = Brush.verticalGradient(
                colors = listOf(SurfaceTeal, AbyssBlack)
            )
        )

        // Stage platform
        val stageHeight = h * 0.25f
        val stageTop = 20f
        drawRoundRect(
            color = SurfaceElevated.copy(alpha = 0.5f),
            topLeft = Offset(20f, stageTop),
            size = Size(w - 40f, stageHeight),
            cornerRadius = androidx.compose.ui.geometry.CornerRadius(8f, 8f)
        )
        drawRoundRect(
            color = CyanDim.copy(alpha = 0.3f),
            topLeft = Offset(20f, stageTop),
            size = Size(w - 40f, stageHeight),
            cornerRadius = androidx.compose.ui.geometry.CornerRadius(8f, 8f),
            style = Stroke(width = 2f)
        )

        // Stage label
        drawStageLabel(w / 2f, stageTop + stageHeight / 2f)

        // PA speakers
        val paLeftX = 40f + 30f
        val paRightX = w - 40f - 30f
        val paY = stageTop + stageHeight / 2f
        val paRadius = 18f

        // SPL zones around PAs
        val zoneColor = when {
            spl >= 100f -> CoralAlert
            spl >= 85f -> AmberAccent
            spl > 0f -> LimeActive
            else -> CyanDim
        }

        for (paX in listOf(paLeftX, paRightX)) {
            drawCircle(
                color = zoneColor.copy(alpha = 0.08f),
                radius = 100f,
                center = Offset(paX, paY)
            )
            drawCircle(
                color = zoneColor.copy(alpha = 0.12f),
                radius = 65f,
                center = Offset(paX, paY)
            )
            drawCircle(
                color = zoneColor.copy(alpha = 0.18f),
                radius = 35f,
                center = Offset(paX, paY)
            )
        }

        // PA circles
        for (paX in listOf(paLeftX, paRightX)) {
            drawCircle(
                brush = Brush.radialGradient(
                    colors = listOf(SurfaceElevated, SurfaceTeal),
                    center = Offset(paX, paY),
                    radius = paRadius
                ),
                radius = paRadius,
                center = Offset(paX, paY)
            )
            drawCircle(
                color = CyanGlow,
                radius = paRadius,
                center = Offset(paX, paY),
                style = Stroke(width = 2f)
            )
            // Speaker icon indicator
            drawCircle(
                color = CyanGlow.copy(alpha = 0.4f),
                radius = 6f,
                center = Offset(paX, paY)
            )
        }

        // Musician position
        val musicianX = w / 2f
        val musicianY = h * 0.72f
        val musicianRadius = 16f

        // Pulsing glow
        val musicianColor = when {
            isOverLimit -> CoralAlert
            spl >= 85f -> AmberAccent
            spl > 0f -> CyanGlow
            else -> CyanDim
        }

        drawCircle(
            color = musicianColor.copy(alpha = pulseAlpha),
            radius = musicianRadius + 20f,
            center = Offset(musicianX, musicianY)
        )
        drawCircle(
            color = musicianColor.copy(alpha = pulseAlpha * 0.5f),
            radius = musicianRadius + 35f,
            center = Offset(musicianX, musicianY)
        )

        // Distance lines to both PAs
        for (paX in listOf(paLeftX, paRightX)) {
            drawLine(
                color = musicianColor.copy(alpha = 0.3f),
                start = Offset(paX, paY),
                end = Offset(musicianX, musicianY),
                strokeWidth = 2f,
                pathEffect = androidx.compose.ui.graphics.PathEffect.dashPathEffect(floatArrayOf(10f, 10f))
            )
        }

        // Musician circle
        drawCircle(
            brush = Brush.radialGradient(
                colors = listOf(musicianColor, musicianColor.copy(alpha = 0.3f)),
                center = Offset(musicianX, musicianY),
                radius = musicianRadius
            ),
            radius = musicianRadius,
            center = Offset(musicianX, musicianY)
        )
        drawCircle(
            color = musicianColor,
            radius = musicianRadius,
            center = Offset(musicianX, musicianY),
            style = Stroke(width = 2f)
        )

        // SPL label near musician
        if (spl > 0f) {
            drawSplLabel(musicianX, musicianY + musicianRadius + 20f, spl, musicianColor)
        }

        // GPS indicator
        if (!hasGpsFix) {
            drawGpsWarning(w / 2f, h - 30f)
        }
    }
}

private fun DrawScope.drawStageLabel(cx: Float, cy: Float) {
    drawText("ESCENARIO", cx, cy)
}

private fun DrawScope.drawSplLabel(cx: Float, cy: Float, spl: Float, color: Color) {
    drawText("%.0f dB".format(spl), cx, cy, color)
}

private fun DrawScope.drawGpsWarning(cx: Float, cy: Float) {
    drawText("Sin GPS", cx, cy, MaterialTheme.colorScheme.outline)
}

private fun DrawScope.drawText(text: String, cx: Float, cy: Float, color: Color = CyanDim) {
    // Note: Canvas doesn't have native text drawing in Compose without Paint
    // Using a simple visual placeholder - actual text shown via overlay in the composable
}

private fun DrawScope.drawTextPlaceholder(text: String, cx: Float, cy: Float, color: Color) {
    // Visual dot placeholder for text positions
    drawCircle(
        color = color.copy(alpha = 0.3f),
        radius = 3f,
        center = Offset(cx, cy)
    )
}

