}

private fun DrawScope.drawTextPlaceholder(text: String, cx: Float, cy: Float, color: Color) {
    // Visual dot placeholder for text positions
    drawCircle(
        color = color.copy(alpha = 0.3f),
        radius = 3f,
        center = Offset(cx, cy)
    )
